settings:
  {{DEV_HOME}}/tools/cache/m2/repository
@@if DEV_PROXY_HOST


      devboot-https
      true
      https
      {{DEV_PROXY_HOST}}
      {{DEV_PROXY_PORT}}
      {{DEV_MAVEN_NON_PROXY_HOSTS}}


      devboot-http
      true
      http
      {{DEV_PROXY_HOST}}
      {{DEV_PROXY_PORT}}
      {{DEV_MAVEN_NON_PROXY_HOSTS}}


@@endif
@@if DEV_MAVEN_MIRROR_URL


      devboot-mirror
      ${env.MAVEN_MIRROR_USERNAME}
      ${env.MAVEN_MIRROR_PASSWORD}




      devboot-mirror
      {{DEV_MAVEN_MIRROR_OF}}
      {{DEV_MAVEN_MIRROR_URL}}


@@endif
